import { Tooltip, Button } from "march/ui"

// periyodik tablodan bir sıra: her elementin adı ipucunda, renkli balonla
const elements = [["H", "Hidrojen"], ["He", "Helyum"], ["Li", "Lityum"], ["C", "Karbon"], ["O", "Oksijen"]]

export function PeriodicTable() {
  return <div sx={{ flex: "row", gap: 2 }}>
    {elements.map(([sym, name]) => <Tooltip text={name!} color="brand-purple" delay={0}>
      <Button size="lg" sx={{ text: "bold" }}>{sym}</Button>
    </Tooltip>)}
  </div>
}

import { Tooltip, IconButton } from "march/ui"
import { bold, italic, link } from "march/icons"

// düzenleyici araçları: IconButton adını zaten ipucu yapar; Tooltip uzun açıklama ve kısayol için
export function EditorTools() {
  return <div sx={{ flex: "row", gap: 1 }}>
    <Tooltip text="Kalın (Ctrl + B)" placement="bottom"><IconButton icon={bold} label="Kalın" title={false} /></Tooltip>
    <Tooltip text="İtalik (Ctrl + I)" placement="bottom"><IconButton icon={italic} label="İtalik" title={false} /></Tooltip>
    <Tooltip text="Bağlantı ekle (Ctrl + K)" placement="bottom" motion="fade"><IconButton icon={link} label="Bağlantı" title={false} /></Tooltip>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { TooltipLab } from "./TooltipLab.tsx"

// TooltipLab'in testleri: kaydedince Testler sekmesinde çalışır
test("odakta ipucu açılır ve hedefe aria-describedby ile bağlanır", async () => {
  const s = renderTest(() => <TooltipLab />)
  s.get(".m-tip-anchor")!.dispatchEvent(new Event("focusin", { bubbles: true }))
  await s.flush(2)
  expect(s.get(".lab-target")?.hasAttribute("aria-describedby")).toBe(true)
})

test("disabled iken ipucu açılmaz", async () => {
  const s = renderTest(() => <TooltipLab />)
  await s.click("İpucunu kapat")
  s.get(".m-tip-anchor")!.dispatchEvent(new Event("focusin", { bubbles: true }))
  await s.flush(2)
  expect(s.get(".lab-target")?.hasAttribute("aria-describedby")).toBe(false)
})
